mapper.select:
        SELECT
        problem.*,
        cp.id as 'project.id',
        cp.name as 'project.name',
        cp.serial_number as 'project.serialNumber',
        cp.short_name as 'project.shortName'
        FROM
        project_qhse_problem AS problem
        INNER JOIN contract_project AS cp on problem.project_id = cp.id and cp.bool_delete_enum = 0
        
            AND cp.name like concat('%',#{projectName},'%')
        
        where problem.bool_delete_enum = 0
        
            AND problem.problem_date >= #{startDate}
        
        
            AND problem.problem_date <= #{endDate}
        
        
            AND problem.project_id = #{projectId}
        
        
            AND problem.problem_type_id = #{problemTypeId}
        
        
            AND problem.bool_change_status = #{boolChangeStatus}
        
        
            AND problem.supplier_id = #{supplierId}
        
        
            AND problem.supplier_name like concat('%',#{supplierName},'%')
        
        
            AND problem.promoter_name like concat('%',#{promoterName},'%')
        
        order by problem.bool_change_status asc, problem.create_time desc

        select pq.*
        from project_qhse_problem as pq
        where pq.bool_delete_enum = 0
        
            AND pq.supplier_id = #{supplierId}
        
        
            AND pq.project_id = #{projectId}
        
        
            AND pq.problem_type_id = #{problemTypeId}
        
        
            AND pq.bool_change_status = #{boolChangeStatus}
        
        order by bool_change_status asc
